package com.weaponsregistration.maintenance.service;import com.weaponsregistration.core.service.UnitScopeGuard;import jakarta.persistence.EntityManager;import org.springframework.http.HttpStatus;import org.springframework.stereotype.Component;import org.springframework.web.server.ResponseStatusException;
@Component public class MaintenanceUnitScopeGuard implements UnitScopeGuard{private final EntityManager em;public MaintenanceUnitScopeGuard(EntityManager em){this.em=em;}public void validateOrganizationChange(long unit,long organization){long n=em.createQuery("select count(w) from WorkOrder w where w.unit.id=:u and w.organization.id<>:o",Long.class).setParameter("u",unit).setParameter("o",organization).getSingleResult();if(n>0)throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"The unit has maintenance history.");}}
